/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void display_prog (UInt8 feature, UInt8 option, Boolean feature_change)
{	
  Display_Cmd display_cmd_new ;

  timeout_stop  (display_timeout) ;	

  display_cmd_new.id = DISPLAY_PROG ;

  display_cmd_new.arg.cmd_prog.feature         = feature        ;
  display_cmd_new.arg.cmd_prog.option          = option         ;
  display_cmd_new.arg.cmd_prog.feature_change  = feature_change ;

  display_pass_cmd (& display_cmd_new) ;
}

